/* Executive display, generic factory identities and contextual factory drawer. */
tabs.splice(0,tabs.length,...tabs.filter(t=>t!=='Connections'));
if(!tabs.includes('Utilities'))tabs.splice(tabs.indexOf('Facility')+1,0,'Utilities');
let activeUtility=0,factoryDrawerArea='Process',factoryDrawerEngineering=false;
const utilityProfiles=[
 {name:'Water',symbol:'◉',color:'#8bd9ff',unit:'m³',total:2640,budget:3000,rate:'6.2 bar',rateLabel:'Supply Pressure',trend:[310,340,325,390,360,430,485],mix:[68,32],mixLabels:['Reused','Fresh Water'],note:'Reuse helps reduce freshwater demand while protecting supply continuity.'},
 {name:'Gas',symbol:'♨',color:'#ffd298',unit:'Nm³',total:18200,budget:22000,rate:'4.1 bar',rateLabel:'Supply Pressure',trend:[2200,2450,2400,2900,2600,2800,2850],mix:[74,26],mixLabels:['Process Heating','Other Uses'],note:'Heating demand follows the production plan. Review peak loads before the next shift.'},
 {name:'Electricity',symbol:'ϟ',color:'#b5a8ff',unit:'MWh',total:418,budget:460,rate:'0.42 kWh/unit',rateLabel:'Energy Intensity',trend:[48,56,53,62,59,68,72],mix:[62,38],mixLabels:['Production','Buildings & Utilities'],note:'Track purchased electricity against budget and the output delivered.'},
 {name:'Power',symbol:'⏻',color:'#a5f7d9',unit:'MW',total:1.24,budget:1.4,rate:'0.97',rateLabel:'Power Factor',trend:[1.1,1.18,1.24,1.3,1.25,1.24],mix:[84,16],mixLabels:['Used Capacity','Available Headroom'],note:'Power is instantaneous demand; electricity is energy consumed over the period.'}
];
function utilityData(i){const u=utilityProfiles[i],days=periodDays(),factor=state.factory<0?1:[.30,.27,.20,.23][state.factory],scale=i===3?factor:days*factor;return {...u,total:+(u.total*scale).toFixed(i===3?2:1),budget:+(u.budget*scale).toFixed(i===3?2:1),trend:u.trend.map(v=>+(v*scale).toFixed(2))}}
function utilityMetricCards(){return utilityProfiles.map((_,i)=>{const u=utilityData(i);return [u.name+(i===3?' Demand':' Consumption'),nfmt(u.total)+' '+u.unit,i===3?'Instantaneous · Demo':'Selected Period · Demo']})}
function utilityDetails(i){activeUtility=i;render()}
function utilityBreakdown(){const u=utilityData(activeUtility);openModal(u.name+' · Usage Breakdown',`<div class="utility-modal-summary"><strong>${nfmt(u.total)} ${u.unit}</strong><p>${escapeHTML(scopeName())} · ${escapeHTML($('#period').value)} · Illustrative Values</p></div>${compositionChart(u.name+' Allocation','Illustrative allocation',u.mixLabels,u.mix,'%')}<p>${u.note}</p>`)}
function utilitiesView(){const u=utilityData(activeUtility),pct=Math.min(100,u.total/u.budget*100),labels=u.trend.length===7?['P1','P2','P3','P4','P5','P6','P7']:['P1','P2','P3','P4','P5','P6'];return `<div class="business-strip"><strong>Utilities Intelligence</strong><span>${escapeHTML(scopeName())} · ${escapeHTML($('#period').value)} · Demo Utility Profile</span><button onclick="utilityBreakdown()">Usage Breakdown ↗</button></div><div class="utilities-workspace"><div class="utility-service-grid">${utilityProfiles.map((_,i)=>{const x=utilityData(i);return `<button class="utility-service ${i===activeUtility?'selected':''}" style="--utility-color:${x.color}" onclick="utilityDetails(${i})" aria-pressed="${i===activeUtility}"><span class="utility-service-heading"><i>${x.symbol}</i><strong>${x.name}</strong><span class="dot"></span></span><b>${nfmt(x.total)} <small>${x.unit}</small></b><span>${i===3?'Current Demand':'Period Consumption'}</span>${smartMiniTrend(x.trend)}<small>${(x.total/x.budget*100).toFixed(0)}% Of ${i===3?'Capacity':'Budget'}</small></button>`}).join('')}</div><section class="panel utility-focus" style="--utility-color:${u.color}"><div class="panelhead"><div><h2>${u.name} · Resource Outlook</h2><small>Illustrative Values · Select A Point For Details</small></div><button onclick="utilityBreakdown()">Inspect ↗</button></div><div class="utility-overview"><button class="utility-budget-ring" style="--fill:${pct}%;--utility-color:${u.color}" onclick="utilityBreakdown()" title="${pct.toFixed(1)}% of ${u.budget} ${u.unit} ${activeUtility===3?'capacity':'budget'}"><span><b>${pct.toFixed(0)}%</b><small>${activeUtility===3?'Capacity Used':'Budget Used'}</small></span></button><div class="utility-summary"><strong>${nfmt(u.total)} <small>${u.unit}</small></strong><span>${activeUtility===3?'Capacity':'Period Budget'}: ${nfmt(u.budget)} ${u.unit}</span><div><small>${u.rateLabel}</small><b>${u.rate}</b></div></div></div>${analyticsChart(u.name+' Profile','Illustrative Period Samples',labels,u.trend,u.unit,{viz:'area'})}<div class="utility-advisory"><span class="dot"></span><span>${u.note}</span></div></section></div>`}
const genericBeforeExecutiveRefresh=generic;generic=function(){return state.tab==='Utilities'?utilitiesView():genericBeforeExecutiveRefresh()};
const metricsBeforeExecutiveRefresh=pageMetrics;pageMetrics=function(){return state.tab==='Utilities'?utilityMetricCards():metricsBeforeExecutiveRefresh()};

function closeFactoryDrawer(){const d=$('#factory-drawer');if(d?.querySelector('.model-ready'))window.disposeOperationsModels?.();d?.close();d?.remove();factoryDrawerEngineering=false}
function factoryDrawerSelect(id){factoryDrawerArea=id;drawFactoryDrawer()}
function factoryDrawerToggleModel(){factoryDrawerEngineering=!factoryDrawerEngineering;drawFactoryDrawer();window.mountOperationsModels?.()}
function drawerFactorySnapshot(){const prior=state.factory;try{state.factory=terrainSelection;return siteSnapshot(terrainSelection)}finally{state.factory=prior}}
function drawFactoryDrawer(){let dialog=$('#factory-drawer');if(dialog?.querySelector('.model-ready'))window.disposeOperationsModels?.();if(!dialog){dialog=document.createElement('dialog');dialog.id='factory-drawer';dialog.setAttribute('aria-label','Factory Data Sidebar');document.body.appendChild(dialog);dialog.addEventListener('cancel',()=>{factoryDrawerEngineering=false});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left)closeFactoryDrawer()}})}const fi=terrainSelection,site=factories[fi],s=drawerFactorySnapshot(),prior=state.factory;let area;try{state.factory=fi;area=smartAreaData(factoryDrawerArea)}finally{state.factory=prior}const art=architectureFor(fi);dialog.innerHTML=`<div class="factory-drawer-head"><div><small>Factory Intelligence</small><h2>${site.name}</h2><span>${site.city}, Egypt · ${fi===2?'Attention':'Operating'}</span></div><button onclick="closeFactoryDrawer()" aria-label="Close Factory Sidebar">✕</button></div><div class="factory-drawer-metrics">${[['Production',s.production+'%'],['Quality',s.quality+'%'],['Delivery',s.delivery+'%'],['Maintenance',s.actions+' Actions']].map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="factory-drawer-campus"><div class="factory-drawer-model-controls"><span>Illustrative Campus</span><button onclick="factoryDrawerToggleModel()">${factoryDrawerEngineering?'Campus Image':'Interactive 3D'}</button></div>${factoryDrawerEngineering?engineeringModelSlot('factory',0,true):`<img src="${art.src}" alt="${site.name} 3D Campus">${campusAreas.map(a=>{const pos=art.positions[a.id]||[a.x,a.y];return `<button class="drawer-area-pin ${a.id===factoryDrawerArea?'active':''}" style="left:${pos[0]}%;top:${pos[1]}%" onclick="factoryDrawerSelect('${a.id}')" title="${escapeHTML(a.name)}">${escapeHTML(a.name)}</button>`}).join('')}`}</div><div class="factory-drawer-areas">${campusAreas.map(a=>`<button class="${a.id===factoryDrawerArea?'active':''}" onclick="factoryDrawerSelect('${a.id}')">${escapeHTML(a.name)}</button>`).join('')}</div><section class="factory-drawer-reading"><div><small>${factoryDrawerArea} · ${area.state}</small><strong>${area.metric} <span>${area.unit}</span></strong><p>${area.detail} · ${area.target}</p></div><p>${area.action}</p></section><div class="factory-drawer-actions"><button onclick="cameraCenter()">CCTV Cameras</button><button onclick="documentCenter('Factory')">Factory Documents</button><button onclick="alarmCenter()">Factory Alarms</button></div>`;if(!dialog.open)dialog.showModal();applyExecutiveLabels(dialog);applyReadableType(dialog);if(factoryDrawerEngineering)window.mountOperationsModels?.()}
exploreTerrainFactory=function(){state.factory=terrainSelection;factoryDrawerArea='Process';factoryDrawerEngineering=false;drawFactoryDrawer()};
enterFactory=function(fi){if(!Number.isInteger(fi)||!factories[fi])return;terrainSelection=fi;state.factory=fi;factoryDrawerArea='Process';factoryDrawerEngineering=false;drawFactoryDrawer()};

const visualBeforeExecutiveRefresh=cameraVisual;
cameraVisual=function(fi,index,compact=false){const c=cameraRecord(fi,index);if(c.url)return visualBeforeExecutiveRefresh(fi,index,compact);const x=index%2?100:0,y=index<2?0:100;return `<div class="factory-camera-frame camera-realistic ${compact?'camera-compact':''} scene-${index}" data-camera-id="${c.id}"><div class="realistic-camera-background" style="background-position:${x}% ${y}%" role="img" aria-label="Simulated ${escapeHTML(c.name)} With Staff"></div><div class="camera-scanline" aria-hidden="true"></div><div class="camera-frame-top"><span>${c.id} · ${escapeHTML(factories[fi].name)}</span><span>SIMULATION</span></div><div class="camera-frame-bottom"><span>${escapeHTML(c.name)}</span><small>${compact?'Illustrative Scene':'Illustrative Scene · Not Live Footage'}</small></div></div>`};
const workspaceBeforeExecutiveRefresh=cctvWorkspace;cctvWorkspace=function(modal=false){const box=document.createElement('div');box.innerHTML=workspaceBeforeExecutiveRefresh(modal);const notice=box.querySelector('.camera-workspace-notice');if(notice)notice.textContent='Simulated Factory Scenes With Staff · Camera Identifiers And Coverage Remain Factory-Specific · Not Live Footage';const location=box.querySelector('.camera-location-note>span');if(location&&!cameraRecord(cameraFactory(),factoryCctv.camera).url)location.textContent='Simulated Scene With Staff';return box.innerHTML};

function applyReadableType(root=document){if(!window.getComputedStyle)return;root.querySelectorAll('main *,#modalbody *,#factory-drawer *,header *,footer *').forEach(el=>{if(el.closest('svg')||['SCRIPT','STYLE','CANVAS','IMG','OPTION'].includes(el.tagName))return;if(![...el.childNodes].some(n=>n.nodeType===3&&n.textContent.trim()))return;const size=parseFloat(window.getComputedStyle(el).fontSize);if(size&&size<14)el.style.setProperty('font-size','14px','important')});root.querySelectorAll('svg.analytics-svg').forEach(svg=>{const width=svg.getBoundingClientRect().width,view=svg.viewBox?.baseVal?.width;if(!width||!view)return;const minimum=14*view/width;svg.querySelectorAll('text').forEach(text=>{const current=parseFloat(window.getComputedStyle(text).fontSize)||16;if(current<minimum)text.style.setProperty('font-size',minimum+'px','important')})})}
function titleWords(text){return text.replace(/(^|[\s/·(–—-])([a-z])/g,(_,gap,c)=>gap+c.toUpperCase())}
function applyExecutiveLabels(root=document){root.querySelectorAll('h1,h2,h3,h4,button,label,th,option,.stage strong,.terrain-site-row strong,.learning-layout td:first-child,.workforce-legend span,.kpis .card>small:first-child,.compact-gauge>small,.workforce-engagement small,svg text,svg tspan').forEach(el=>{if(el.matches('option')&&!el.hasAttribute('value'))el.setAttribute('value',el.textContent);[...el.childNodes].filter(n=>n.nodeType===3).forEach(n=>{n.textContent=titleWords(n.textContent)})})}
const toolsBeforeExecutiveRefresh=compactWorkspaceTools;compactWorkspaceTools=function(){toolsBeforeExecutiveRefresh();$('#modalbody button[onclick*="Connections"]')?.remove();applyExecutiveLabels($('#modalbody'));applyReadableType()};
const goBeforeExecutiveRefresh=go;go=function(tab){if(tab==='Connections')tab='Utilities';if(tab==='Workforce Mgmt')tab='Workforce';closeFactoryDrawer();goBeforeExecutiveRefresh(tab)};
const modalBeforeExecutiveRefresh=openModal;openModal=function(title,body){modalBeforeExecutiveRefresh(titleWords(title),body);applyExecutiveLabels($('#modalbody'));applyReadableType()};
const renderBeforeExecutiveRefresh=render;render=function(){renderBeforeExecutiveRefresh();document.querySelectorAll('#nav button').forEach(b=>{if(b.textContent.trim()==='Connections')b.remove()});document.body.classList.add('executive-readable');applyExecutiveLabels();applyReadableType();const nav=$('#nav');nav?.style.setProperty('--nav-count',String(tabs.length))};
render();
